/**
 * Build the test fixture.
 *
 * The fixture is **synthetic**: every value here is generated by the seeded
 * pseudo-random generator below. It reproduces the shape of a DSH
 * `assistant/message` event (provider, model, usage, turn/step, timestamp) so
 * the pipeline tests exercise the real code paths, but it contains no session
 * log, no real provider or model id, no real timestamp and no real usage.
 *
 * The shape itself was validated against real session logs during development;
 * only the values are invented.
 *
 * Usage: node test/build-fixture.mjs
 */
import { mkdirSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const outFile = join(here, 'fixtures', 'usage-events.json')

// Deterministic PRNG so the fixture is reproducible byte for byte.
let seed = 20260302
function random() {
  seed = (seed * 1664525 + 1013904223) % 4294967296
  return seed / 4294967296
}
const between = (low, high) => low + Math.floor(random() * (high - low + 1))
const pick = (items) => items[Math.floor(random() * items.length)]

// The same model id appears under several providers, which is exactly what the
// identity test needs to prove.
const PROVIDERS = [
  { id: 'provider-a', models: ['model-alpha', 'model-beta'] },
  { id: 'provider-b', models: ['model-gamma'] },
  { id: 'provider-c', models: ['model-alpha', 'model-delta'] },
  { id: 'provider-d', models: ['model-alpha'] },
]

const SESSIONS = 24
const MESSAGES = 500
const STEP_ENDS = 5
// A fixed instant, so the fixture never drifts with the wall clock.
const START = Date.UTC(2026, 2, 2, 9, 0, 0)

const events = []
let seq = 0
let turn = 1
let step = 0

for (let index = 0; index < MESSAGES; index++) {
  const sessionId = `fixture-${(index % SESSIONS) + 1}`
  const provider = pick(PROVIDERS)
  const model = pick(provider.models)
  const time = START + index * 37 * 60 * 1000 + between(0, 45) * 1000
  step += 1
  if (step > 12) { step = 1; turn += 1 }
  seq += 1

  // Roughly one message in a hundred carries no usage, mirroring a provider
  // that occasionally omits it.
  const hasUsage = random() > 0.01
  const input = between(180, 3000)
  const output = between(40, 900)
  const cacheRead = random() < 0.8 ? between(2000, 150000) : 0
  const cacheWrite = random() < 0.15 ? between(200, 3000) : 0
  const reasoning = random() < 0.3 ? Math.floor(output * 0.4) : null

  events.push({
    sessionId,
    type: 'assistant/message',
    seq,
    time,
    turn,
    step,
    provider: provider.id,
    model,
    usage: hasUsage
      ? {
        inputTokens: input,
        outputTokens: output,
        totalTokens: input + output + cacheRead + cacheWrite,
        cacheReadTokens: cacheRead,
        cacheWriteTokens: cacheWrite,
        ...(reasoning === null ? null : { reasoningTokens: reasoning }),
      }
      : null,
  })
}

// A few steps that ended without producing a message, so the "unknown" path is
// covered by the fixture too.
for (let index = 0; index < STEP_ENDS; index++) {
  seq += 1
  events.push({
    sessionId: `fixture-${index + 1}`,
    type: 'step/end',
    seq,
    time: START + (MESSAGES + index) * 37 * 60 * 1000,
    turn: 99,
    step: 90 + index,
    provider: null,
    model: null,
    usage: null,
  })
}

events.sort((a, b) => a.time - b.time || a.seq - b.seq)

// Independent expectation: the totals the recorder must reproduce.
let expectTotal = 0
let expectInput = 0
let expectOutput = 0
let expectCache = 0
let expectKnown = 0
let expectUnknown = 0
const byProviderModel = {}
for (const event of events) {
  if (event.type !== 'assistant/message') { expectUnknown++; continue }
  const usage = event.usage
  if (!usage || typeof usage.inputTokens !== 'number' || typeof usage.outputTokens !== 'number') {
    expectUnknown++
    continue
  }
  expectKnown++
  expectInput += usage.inputTokens
  expectOutput += usage.outputTokens
  expectCache += (usage.cacheReadTokens ?? 0) + (usage.cacheWriteTokens ?? 0)
  const total = typeof usage.totalTokens === 'number'
    ? usage.totalTokens
    : usage.inputTokens + usage.outputTokens + (usage.cacheReadTokens ?? 0) + (usage.cacheWriteTokens ?? 0)
  expectTotal += total
  const key = `${event.provider}\u0000${event.model}`
  byProviderModel[key] = byProviderModel[key] ?? { provider: event.provider, model: event.model, total: 0, count: 0 }
  byProviderModel[key].total += total
  byProviderModel[key].count++
}

const fixture = {
  note: 'Synthetic fixture. The event shape mirrors a DSH assistant/message event; every value is generated, no real usage data is included.',
  source: 'generated by test/build-fixture.mjs',
  events,
  expected: {
    events: events.length,
    known: expectKnown,
    unknown: expectUnknown,
    total: expectTotal,
    input: expectInput,
    output: expectOutput,
    cache: expectCache,
    byProviderModel: Object.values(byProviderModel).sort((a, b) => b.total - a.total),
  },
}

mkdirSync(dirname(outFile), { recursive: true })
writeFileSync(outFile, JSON.stringify(fixture), 'utf8')
console.log(JSON.stringify({
  events: fixture.events.length,
  sessions: SESSIONS,
  expected: { ...fixture.expected, byProviderModel: fixture.expected.byProviderModel.length + ' groups' },
  bytes: JSON.stringify(fixture).length,
}, null, 2))
